def factors(value):
    factor_list = []
    divisor = 2
    while value > 2:
        while value % divisor == 0:
            factor_list.append(divisor)
            value /= divisor
        divisor += 1
    return factor_list

def proverb(*rhyme_items, qualifier):
    print(rhyme_items)
    if not rhyme_items:
        return []
    phrases = [f'For want of a {element_1} the {element_2} was lost.' for (element_1, element_2) in zip(rhyme_items, rhyme_items[2:])]
